//! Observe real entities generated by the locked Rust producer, not local stand-ins.
use serde_json::{Value as Json, json};
use std::{io::{self, BufRead}, sync::Arc};
use teaql_core::{CompactRow, CompactRowLayout, Entity, Value};

macro_rules! observe {
    ($model:ty, $input:expr) => {{
        let input = $input;
        let mut names = vec!["id".to_owned(), "version".to_owned()];
        let mut values = vec![Value::U64(1), Value::I64(1)];
        for name in input["names"].as_array().unwrap() {
            let name = name.as_str().unwrap();
            names.push(name.to_owned());
            values.push(if input["null"].as_bool().unwrap() {
                Value::Null
            } else {
                Value::Text(name.to_owned())
            });
        }
        let row = <$model>::from_compact_row(CompactRow::with_layout(
            CompactRowLayout::new(Arc::<[String]>::from(names)), values,
        )).unwrap();
        let mut loaded = serde_json::Map::new();
        for name in ["id", "version", "type", "type_field", "legacy_type", "type_typo"] {
            loaded.insert(name.to_owned(), json!(row.is_field_loaded(name)));
        }
        json!({"value": row.type_field(), "loaded": loaded,
               "dirty": row.dirty_fields().is_some(), "new": row.is_new()})
    }};
}

fn main() {
    for line in io::stdin().lock().lines() {
        let input: Json = serde_json::from_str(&line.unwrap()).unwrap();
        let output = if input["model"] == "record" {
            observe!(cpp_member_aliases_core::Record, &input)
        } else {
            observe!(cpp_member_aliases_core::ChildRecord, &input)
        };
        println!("{output}");
    }
}
